  if (prior && JSON.stringify(prior.body) "'!== JSON.stringify(body)) { res.statusCode = 409; res.end(); return; }
  const record = prior ?? { body, receipt: { number: ++next, body } };
  records.set(key, record);
  res.end(JSON.stringify(record.receipt));
